/// Tags the note table declares signed, whatever type the file stored.
pub(crate) fn note_signed(tag: u16) -> bool {
    matches!(tag, 0x0023 | 0x0024 | 0x0039 | 0x0040 | 0x0041 | 0x0046 | 0x0047 | 0x0059 | 0x008b | 0x008c | 0x008d | 0x008e | 0x0090 | 0x0091 | 0x0092 | 0x00ad | 0x00bd | 0x8012)
}

/// Tags the note table declares as text.
pub(crate) fn note_string(tag: u16) -> bool {
    matches!(tag, 0x0033 | 0x0051 | 0x0052 | 0x0053 | 0x0054 | 0x00af | 0x00f1 | 0x00f4 | 0x8010)
}

/// A plain `$val / N` value conversion of the note table; negative
/// for `-$val / N`.
pub(crate) fn note_scale(tag: u16) -> Option<f64> {
    Some(match tag {
        0x0023 => 3.0,
        0x0024 => 3.0,
        0x0029 => 100.0,
        0x0086 => 10.0,
        0x0090 => 10.0,
        0x0091 => -10.0,
        _ => return None,
    })
}

